// Generator, not a test. `run.sh` copies this file into the Conn monorepo's apps/server/src and
// runs it with vitest. It writes, for every Claude model in T3's bundled catalog, what
// compileClaudeModelSelection gives for each effort choice and each boolean option, so the Conn
// Server compiles a model selection exactly as the T3 server does (src/model_catalog.json).
// @effect-diagnostics nodeBuiltinImport:off -- writes the generated file
import * as NodeFS from "node:fs";
import { ProviderInstanceId, type ModelSelection } from "@t3tools/contracts";
import { getProviderOptionDescriptors } from "@t3tools/shared/model";
import { it } from "vite-plus/test";

import { compileClaudeModelSelection } from "./claudeModelOptions.ts";
import {
  BUNDLED_CLAUDE_MODEL_CATALOG,
  CLAUDE_EFFORT_LEVELS,
  getClaudeCatalogModelCapabilities,
} from "./provider/ClaudeModelCatalog.ts";

const OUT = process.env.CATALOG_OUT ?? "";

it("dumps the Claude catalog", () => {
  const instanceId = ProviderInstanceId.make("claudeAgent");
  const compile = (model: string, options: ModelSelection["options"]) => {
    const c = compileClaudeModelSelection({ instanceId, model, ...(options ? { options } : {}) });
    return { apiModelId: c.apiModelId, effort: c.effort ?? null, promptEffort: c.promptEffort ?? null, settings: c.settings };
  };
  const models = BUNDLED_CLAUDE_MODEL_CATALOG.models.map((entry) => {
    const slug = entry.model.slug;
    const descriptors = getProviderOptionDescriptors({
      caps: getClaudeCatalogModelCapabilities(BUNDLED_CLAUDE_MODEL_CATALOG, slug),
    });
    const booleans = descriptors.filter((d) => d.type === "boolean").map((d) => d.id);
    const efforts: Record<string, unknown> = { "": compile(slug, undefined) };
    for (const effort of [...CLAUDE_EFFORT_LEVELS, "ultrathink"]) {
      efforts[effort] = compile(slug, [{ id: "effort", value: effort }]);
    }
    const flags: Record<string, unknown> = {};
    for (const id of booleans) {
      flags[`${id}=true`] = compile(slug, [{ id, value: true }]);
      flags[`${id}=false`] = compile(slug, [{ id, value: false }]);
    }
    return { slug, aliases: entry.model.aliases ?? [], booleans, efforts, flags };
  });
  // The models the T3 server offers clients (`ServerProvider.models`), with their option
  // descriptors (effort, thinking, ...), in catalog order. T3 filters them by the CLI's version
  // (`resolveClaudeModelsForVersion`), so each carries its Claude Code bounds
  // (`compatibility`: `minVersion`, `maxVersionExclusive`).
  const providerModels = BUNDLED_CLAUDE_MODEL_CATALOG.models.map((entry) => entry.model);
  const compatibility = BUNDLED_CLAUDE_MODEL_CATALOG.models.map((entry) => ({
    slug: entry.model.slug,
    ...entry.compatibility,
  }));
  NodeFS.writeFileSync(OUT, `${JSON.stringify({ note: "Generated by tools/gen-catalog from T3's BUNDLED_CLAUDE_MODEL_CATALOG with compileClaudeModelSelection. Do not edit.", models, providerModels, compatibility }, null, 1)}\n`);
});
